const SECRET = global.get('JWT_SECRET');
const API_KEY = env.get("API_KEY");
const FLOW_USER = flow.get("$parent.authorized_user");

// 1. API KEY CHECK (Bearer Token)
const auth = msg.req.headers.authorization;
if (API_KEY && auth === `Bearer ${API_KEY}`) {
    return [msg, null]; 
}

// 2. JWT COOKIE CHECK
if (FLOW_USER && SECRET) {
    const tokenName = `auth_token_${FLOW_USER.replace(/\s+/g, '_')}`;
    const token = msg.req.cookies?.[tokenName];

    if (token) {
        try {
            const decoded = jsonwebtoken.verify(token, SECRET);
            // Verify the token belongs to the user assigned to this specific tab
            if (decoded.sub === FLOW_USER) {
                return [msg, null];
            }
        } catch (err) {
            // Token expired or tampered with - fall through to 401
        }
    }
}

// 3. UNAUTHORIZED
msg.statusCode = 401;
msg.payload = { error: "Unauthorized", message: "Invalid or missing credentials" };
return [null, msg];

const USER = env.get("Username");
const PASS = env.get("Password");
const SECRET = global.get('JWT_SECRET');
const REDIRECT = env.get("Redirect");

// 1. SYSTEM CHECK: Ensure subflow is properly configured
if (!USER || !PASS || !SECRET || !REDIRECT) {
    node.error("Subflow configuration error: Missing Username, Password, Secret, or Redirect.");
    msg.statusCode = 500;
    msg.payload = { error: "Internal Server Error", message: "Module misconfigured" };
    return msg; 
}

// Set identity for the 'Verify' node on this flow tab
flow.set("$parent.authorized_user", USER);

const auth = msg.req.headers.authorization;

// 2. AUTHENTICATION LOGIC
if (auth?.startsWith('Basic ')) {
    const encoded = auth.substring(6);
    const [u, p] = Buffer.from(encoded, 'base64').toString().split(':');

    // Verify credentials
    if (u === USER && p === PASS) {
        // Create token (1 hour expiry)
        const token = jsonwebtoken.sign({ sub: u }, SECRET, { expiresIn: '1h' });

        // Scope cookie name to the user to allow multiple logins
        const cookieName = `auth_token_${u.replace(/\s+/g, '_')}`;

        msg.cookies = { 
            [cookieName]: { 
                value: token, 
                httpOnly: true, 
                path: '/',
                sameSite: 'Strict'
            } 
        };

        // redirect if successful
        msg.statusCode = 302;
        msg.headers = { 'Location': REDIRECT };
        return msg;
    }
}

// 3. UNAUTHORIZED
msg.statusCode = 401;
msg.headers = { 'WWW-Authenticate': 'Basic realm="Restricted Area"' };
msg.payload = { error: "Unauthorized", message: "Authentication required" };
return msg;

