msg.headers = {
    "Cache-Control": "no-store, no-cache, must-revalidate, proxy-revalidate",
    "Pragma": "no-cache",
    "Expires": "0"
};
return msg;

if (msg.isActive === false) {
    node.warn("User is not signed in")
    return null;
}

function getCalendarUrl() {
    const now = new Date();

    // Start: před 0 dny (00:00)
    const startDate = new Date(now);
    startDate.setDate(now.getDate());
    startDate.setHours(0, 0, 0, 0);

    // End: za 5 dní (23:59)
    const endDate = new Date(now);
    endDate.setDate(now.getDate() + 5);
    endDate.setHours(23, 59, 59, 999);

    const startISO = startDate.toISOString();
    const endISO = endDate.toISOString();

    const selectFields = "subject,start,end,attendees,lastModifiedDateTime,organizer";

    return `/me/calendarView?startDateTime=${startISO}&endDateTime=${endISO}&$select=${selectFields}`;
}

msg.payload = {

    "method": "GET",
    "endpoint": getCalendarUrl()
}
return msg;

let start = new Date(msg.payload.value.start.dateTime + "Z");
let end = new Date(msg.payload.value.end.dateTime + "Z");

// start a konec posunout o hodinu (návštěvník přijde několik minut před naplánovou schůzkou a několik minut po ní)
start.setHours(start.getHours() - 1);
end.setHours(end.getHours() + 1);

// převést čas na lokální
msg.accessStartTime = start.toLocaleString();
msg.accessEndTime = end.toLocaleString();

// nastav proměnné
msg.organizerEmail = msg.payload.value.organizer.emailAddress.address
msg.organizerName = msg.payload.value.organizer.emailAddress.name

msg.eventId = "ms_graph|" + msg.payload.value.id;
msg.email = msg.payload.value.attendees.emailAddress.address
msg.fullName = msg.payload.value.attendees.emailAddress.name


// Odfiltruj uživatele se stejnou doménou
const organizerDomain = msg.organizerEmail.split('@')[1];
const attendeeDomain = msg.email.split('@')[1];

if (organizerDomain === attendeeDomain) {
    return null;
}

// najdi existující uživatele
msg.query = `?filter={"$and":[{"Email":{"$eq":"${msg.email}"}},{"Note":{"$eq":"${msg.eventId}"}}]}`

return msg;

msg.visitorId = msg.payload.Id
msg.companyId = msg.payload.Company.Id
return msg;

